from pyats import aetest


class CommonSetup(aetest.CommonSetup):
    @aetest.subsection
    def connect(self, testbed):
        for dev in testbed.devices.values():
            dev.connect(log_stdout=False)      # fails the run early if unreachable


class OspfNeighbors(aetest.Testcase):
    @aetest.test
    def all_neighbors_full(self, testbed):
        for name, dev in testbed.devices.items():
            out = dev.parse("show ip ospf neighbor")      # structured data, not text
            states = [
                n["state"]
                for intf in out["interfaces"].values()
                for n in intf["neighbors"].values()
            ]
            assert states, f"{name}: no OSPF neighbors"
            bad = [s for s in states if not s.startswith("FULL")]
            assert not bad, f"{name}: neighbors not FULL: {bad}"


class CommonCleanup(aetest.CommonCleanup):
    @aetest.subsection
    def disconnect(self, testbed):
        for dev in testbed.devices.values():
            dev.disconnect()


if __name__ == "__main__":
    aetest.main()

